import React, { useEffect, useState } from "react";
import AdminNavbar from "../Components/AdminNavbar";
import Footer from "../Components/Footer";
import "../styles/AdminPages.css";
import API_BASE_URL from "../config";

const Reports = () => {
  const [reports, setReports] = useState([]);

  // 🔄 Load reports from the backend
  useEffect(() => {
    fetch(`${API_BASE_URL}/api/admin/reports`)
      .then((res) => res.json())
      .then((data) => {
        console.log("Fetched reports:", data);
        if (Array.isArray(data)) {
          setReports(data);
        } else {
          setReports([]);
        }
      })
      .catch((err) => {
        console.error("Failed to fetch reports:", err);
        setReports([]);
      });
  }, []);

  // ❌ Dismiss a report
  const dismissReport = async (id) => {
    const res = await fetch(`${API_BASE_URL}/api/admin/reports/${id}`, {
      method: "DELETE",
    });

    if (res.ok) {
      setReports(reports.filter((r) => r.id !== id));
    } else {
      alert("Failed to dismiss report.");
    }
  };

  return (
    <div>
      <AdminNavbar />
      <main className="favorites-wrapper">
        <h2>User Reports</h2>
        <div className="favorites-grid">
          {Array.isArray(reports) && reports.length > 0 ? (
            reports.map((report) => (
              <div className="favorite-card" key={report.id}>
                <h4>{report.item || "Unknown Item"}</h4>
                <p><strong>Reported by:</strong> {report.reporter || "Anonymous"}</p>
                <p><strong>Reason:</strong> {report.reason || "No reason provided"}</p>
                <button className="remove-btn" onClick={() => dismissReport(report.id)}>
                  Dismiss Report
                </button>
              </div>
            ))
          ) : (
            <p>No reports found.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Reports;
